from typing import FrozenSet

Prop = FrozenSet[int]


def box(s: Prop, n: int) -> Prop:
    """Provability operator of the frame (N, <): n proves S iff every m < n is in S."""
    return frozenset(k for k in range(n) if all(m in s for m in range(k)))


def loeb_fixed_point(a: Prop, n: int) -> Prop:
    """Compute box(box A => A); equals box A by the de Jongh-Sambin theorem."""
    universe = frozenset(range(n))
    box_a = box(a, n)
    himp = (universe - box_a) | a          # box A => A  (Boolean implication)
    return box(himp, n)

algorithms.pseudocode:
function box(S, n):
    R := empty set
    for k in 0..n-1:
        if for all m < k:  m in S  then add k to R
    return R

function loeb_fixed_point(A, n):
    U      := {0,...,n-1}
    boxA   := box(A, n)
    himp   := (U \ boxA) union A      # boxA => A
    return box(himp, n)               # provably equals boxA

function provability_rank_spectrum(n, kmax):
    spectrum := empty list
    cur := empty set          # BOT
    for k in 0..kmax:
        append (k, cur) to spectrum
        cur := box(cur, n)    # = {0,...,k}
    return spectrum

function verify_gl_axioms(n):
    U := {0,...,n-1}
    assert box(U, n) == U                              # box_top
    for A in all subsets of U:
        boxA := box(A, n)
        assert box((U\boxA) union A, n) subset boxA   # Loeb
        assert boxA subset box(boxA, n)                # axiom 4
        for B in all subsets of U:
            assert box(A inter B, n) == box(A,n) inter box(B,n)  # axiom K
    return True
